import { randomBytes } from "node:crypto";
import { createReadStream } from "node:fs";
import { mkdir, rm, stat, writeFile } from "node:fs/promises";
import path from "node:path";
import type { Readable } from "node:stream";

/** URL prefix under which stored files are served. */
export const UPLOADS_PATH = "/uploads";

// Keys are generated by the server only; anything else is refused before touching the disk.
const KEY_PATTERN = /^(?:[a-z0-9]+\/)*[A-Za-z0-9_-]+\.webp$/;

export const isValidKey = (key: string) => KEY_PATTERN.test(key) && !key.includes("..");

/** A unique key for a new file, e.g. "cafes/<cafeId>/products/<productId>-<random>.webp". */
export function newImageKey(folder: string, name: string): string {
  return `${folder}/${name}-${randomBytes(6).toString("base64url")}.webp`;
}

/**
 * Where uploaded files live: local disk, which in production is a persistent volume. A bucket
 * (e.g. Cloudflare R2) could implement the same interface if the app outgrows one server.
 */
export interface FileStorage {
  /** Saves the file and returns its public URL. */
  put(key: string, data: Buffer, contentType: string): Promise<string>;
  /** Deletes the file behind a URL this storage returned; unknown URLs are ignored. */
  removeByUrl(url: string): Promise<void>;
}

export function createLocalStorage(rootDir: string) {
  const root = path.resolve(rootDir);
  const fileFor = (key: string) => {
    if (!isValidKey(key)) throw new Error(`Invalid storage key: ${key}`);
    return path.join(root, ...key.split("/"));
  };
  const keyFromUrl = (url: string) =>
    url.startsWith(`${UPLOADS_PATH}/`) ? url.slice(UPLOADS_PATH.length + 1) : null;

  return {
    async put(key: string, data: Buffer): Promise<string> {
      const file = fileFor(key);
      await mkdir(path.dirname(file), { recursive: true });
      await writeFile(file, data);
      return `${UPLOADS_PATH}/${key}`;
    },

    async removeByUrl(url: string): Promise<void> {
      const key = keyFromUrl(url);
      if (key && isValidKey(key)) await rm(fileFor(key), { force: true });
    },

    /** Opens a stored file for serving, or null if there is none. */
    async open(key: string): Promise<{ stream: Readable; size: number } | null> {
      if (!isValidKey(key)) return null;
      const file = fileFor(key);
      try {
        const info = await stat(file);
        if (!info.isFile()) return null;
        return { stream: createReadStream(file), size: info.size };
      } catch {
        return null;
      }
    },
  } satisfies FileStorage & Record<string, unknown>;
}

export type LocalStorage = ReturnType<typeof createLocalStorage>;
